Only src/main/ai/anthropic.ts (`anthropicFailure`) needs to change. When the SDK error has no HTTP status, work out a status from the stream error's type, and show the error body's `error.message` instead of the stringified JSON:

```ts
/** Statuses that SSE `error` events (sent after HTTP 200) stand for. */
const STREAM_ERROR_STATUS: Record<string, number> = { overloaded_error: 529, api_error: 500, rate_limit_error: 429, timeout_error: 408 }

if (err instanceof Anthropic.APIError) {
  const code = err.type ?? undefined
  const status = err.status ?? (code ? STREAM_ERROR_STATUS[code] : undefined)
  const inner = (err.error as { error?: { message?: unknown } } | undefined)?.error?.message
  return { status, code, message: typeof inner === 'string' ? inner : err.message, retryAfter: retryAfterSeconds(err.headers?.get('retry-after')) }
}
```

